// Environment: streams pooled 84 m road chunks around the player, owns lights, sky, fog and shared materials.
// Chunks are generated by scenery/ChunkBuilder.js. Add a new Dhaka area by adding an entry to config/zones.js.
import * as THREE from 'three';
import { GeoBuilder, setAtlasCells } from './geo.js';
import { createSignAtlas, createFacadeTexture } from './Textures.js';
import { buildChunk, zoneInfo } from './scenery/ChunkBuilder.js';
import { WORLD } from '../config/gameConfig.js';
import { ZONES } from '../config/zones.js';
import { clamp } from './utils.js';

// vertex capacity per layer (checked for overflow in dev: see console warnings)
const CAP = { solid: 24000, facade: 3000, glass: 2000, sign: 1600, glow: 1800 };
const LAYERS = Object.keys(CAP);

const SKY_VERT = /* glsl */ `varying vec3 vP; void main(){ vP = position; gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0); }`;
const SKY_FRAG = /* glsl */ `
uniform vec3 uTop; uniform vec3 uBottom; varying vec3 vP;
void main(){
  float h = normalize(vP).y;
  vec3 c = mix(uBottom, uTop, smoothstep(-0.02, 0.55, h));
  gl_FragColor = vec4(c, 1.0);
  #include <colorspace_fragment>
}`;

class Chunk {
  constructor(scene, mats, caps) {
    this.index = null;
    this.layers = {};
    this.meshes = {};
    this.obstacles = [];
    this.stops = [];
    this.info = null;
    this.group = new THREE.Group();
    for (const key of LAYERS) {
      const b = new GeoBuilder(Math.round(CAP[key] * caps));
      this.layers[key] = b;
      const geo = b.makeDynamicGeometry();
      const mesh = new THREE.Mesh(geo, mats[key]);
      mesh.frustumCulled = false;
      mesh.visible = false;
      this.group.add(mesh);
      this.meshes[key] = mesh;
    }
    this.group.visible = false;
    scene.add(this.group);
  }

  build(k) {
    this.index = k;
    this.warned = false;
    buildChunk(this, k);
    for (const key of LAYERS) {
      const b = this.layers[key];
      b.commit(this.meshes[key].geometry);
      this.meshes[key].visible = b.i > 0;
    }
    this.group.visible = true;
  }

  release() { this.index = null; this.group.visible = false; this.stops.length = 0; this.obstacles.length = 0; }

  dispose() { for (const key of LAYERS) this.meshes[key].geometry.dispose(); this.group.removeFromParent(); }
}

export class Environment {
  constructor(scene, { low = false } = {}) {
    this.scene = scene;
    this.low = low;
    this.len = WORLD.chunkLength;
    this.ahead = low ? WORLD.chunksAhead - 1 : WORLD.chunksAhead;
    this.behind = WORLD.chunksBehind;

    // lights
    this.hemi = new THREE.HemisphereLight(0xe3edf7, 0x8c7c68, 1.35);
    this.sun = new THREE.DirectionalLight(0xfff1d6, 1.55);
    this.sun.position.set(-40, 80, 55);
    scene.add(this.hemi, this.sun);

    // textures & materials
    this.atlas = createSignAtlas();
    setAtlasCells(this.atlas.cells);
    this.facadeTex = createFacadeTexture('concrete');
    this.glassTex = createFacadeTexture('glass');
    this.mats = {
      solid: new THREE.MeshLambertMaterial({ vertexColors: true }),
      facade: new THREE.MeshLambertMaterial({ vertexColors: true, map: this.facadeTex }),
      glass: new THREE.MeshLambertMaterial({ vertexColors: true, map: this.glassTex, emissive: 0x0a1218 }),
      sign: new THREE.MeshBasicMaterial({ vertexColors: true, map: this.atlas.texture }),
      glow: new THREE.MeshBasicMaterial({ vertexColors: true }),
    };

    // sky dome (follows the camera) + fog
    this.skyUniforms = { uTop: { value: new THREE.Color(0x7fa8c9) }, uBottom: { value: new THREE.Color(0xcdd3d4) } };
    this.sky = new THREE.Mesh(
      new THREE.SphereGeometry(600, 16, 10),
      new THREE.ShaderMaterial({ vertexShader: SKY_VERT, fragmentShader: SKY_FRAG, uniforms: this.skyUniforms, side: THREE.BackSide, depthWrite: false, fog: false }),
    );
    this.sky.frustumCulled = false;
    this.sky.renderOrder = -10;
    scene.add(this.sky);
    this.fogColor = new THREE.Color(0xcdd3d4);
    scene.fog = new THREE.Fog(this.fogColor, low ? 70 : 90, low ? 250 : 330);
    scene.background = this.fogColor;

    // chunk pool
    const poolSize = this.ahead + this.behind + 2;
    const caps = low ? 0.8 : 1;
    this.pool = Array.from({ length: poolSize }, () => new Chunk(scene, this.mats, caps));
    this.byIndex = new Map();
    this._tmpColor = new THREE.Color();
    this._tmpColor2 = new THREE.Color();
    this.currentZone = ZONES[0];
  }

  /** Build everything around z synchronously (loading screen / restart). */
  reset(z = 0) {
    for (const c of this.pool) c.release();
    this.byIndex.clear();
    this.update(z, 0, true);
    this.applyAtmosphere(z, 1);
  }

  chunkIndexAt(z) { return Math.floor(-z / this.len); }

  /** Stream chunks around the player. Builds at most one chunk per call unless `all` is set. */
  update(playerZ, dt, all = false) {
    const c = this.chunkIndexAt(playerZ);
    const lo = c - this.behind, hi = c + this.ahead;
    // free chunks that left the window
    for (const [k, chunk] of this.byIndex) {
      if (k < lo || k > hi) { chunk.release(); this.byIndex.delete(k); }
    }
    // build missing ones, nearest first
    let built = 0;
    const order = [];
    for (let k = lo; k <= hi; k++) if (!this.byIndex.has(k)) order.push(k);
    order.sort((a, b) => Math.abs(a - c) - Math.abs(b - c));
    for (const k of order) {
      const chunk = this.pool.find((p) => p.index === null);
      if (!chunk) break;
      chunk.build(k);
      this.byIndex.set(k, chunk);
      if (!all && ++built >= 1) break;
    }
  }

  zoneAt(z) { return zoneInfo(this.chunkIndexAt(z)); }

  /** Call cb(x, z, hw, hl) for every solid obstacle overlapping the z range. */
  queryObstacles(z0, z1, cb) {
    const kLo = this.chunkIndexAt(z1), kHi = this.chunkIndexAt(z0);
    for (let k = kLo; k <= kHi; k++) {
      const ch = this.byIndex.get(k);
      if (!ch) continue;
      for (const o of ch.obstacles) if (o.z >= z0 - 2 && o.z <= z1 + 2) cb(o.x, o.z, o.hw, o.hl);
    }
  }

  /** Call cb(stop) for every bus stop with z in [z0, z1]. */
  forEachStop(z0, z1, cb) {
    const kLo = this.chunkIndexAt(z1), kHi = this.chunkIndexAt(z0);
    for (let k = kLo; k <= kHi; k++) {
      const ch = this.byIndex.get(k);
      if (!ch) continue;
      for (const s of ch.stops) if (s.z >= z0 && s.z <= z1) cb(s);
    }
  }

  /** Fog / sky colours blend into the next area over the last 2 chunks of the current one. */
  applyAtmosphere(z, k = 1) {
    const info = this.zoneAt(z);
    const posInZone = (-z / this.len) - Math.floor(Math.max(0, -z / this.len) / WORLD.zoneChunks) * WORLD.zoneChunks;
    const next = ZONES[(info.zi + 1) % ZONES.length];
    const t = clamp((posInZone - (WORLD.zoneChunks - 2)) / 2, 0, 1);
    this._tmpColor.setHex(info.zone.fog);
    this._tmpColor2.setHex(next.fog);
    this._tmpColor.lerp(this._tmpColor2, t);
    this.fogColor.lerp(this._tmpColor, k);
    this.skyUniforms.uBottom.value.copy(this.fogColor);
    this.skyUniforms.uTop.value.setHex(0x6f9bc4).lerp(this.fogColor, 0.18);
    this.currentZone = info.zone;
  }

  followCamera(cameraPos, playerZ, dt) {
    this.sky.position.copy(cameraPos);
    this.sun.position.set(cameraPos.x - 40, 80, cameraPos.z + 55);
    this.sun.target.position.set(cameraPos.x, 0, cameraPos.z);
    this.sun.target.updateMatrixWorld();
    this.applyAtmosphere(playerZ, clamp(dt * 1.5, 0, 1));
  }

  /** Re-draw the sign atlas once the Bengali web font has loaded. */
  refreshTextures() { this.atlas.redraw(); }

  dispose() {
    for (const c of this.pool) c.dispose();
    for (const m of Object.values(this.mats)) m.dispose();
    this.atlas.texture.dispose(); this.facadeTex.dispose(); this.glassTex.dispose();
    this.sky.geometry.dispose(); this.sky.material.dispose();
    this.scene.remove(this.hemi, this.sun, this.sky);
  }
}
